"""Рядки 5293/6995: 19 записів `аудит/перевірка/5293/спори_очима.json` (ФОТО-1 #1331) на поточному коді — фото стенда
`ОЦІНКА_ФІГУРИ` (`аудит/проби/рв6_стенд.js`) намальовано тут, кадр рамки — як `пікселіРечіП` показу (поле 0,12, ≤ 128 px),
вимір — `оцінка_образу._виміри` + `_без_кадру`. Друкує по запису: що поміряно тепер і чи колір лишився виміром.
Вердикти: <тека>/<гілка без claude/>__<перші 2 знаки теки>/вердикти.txt (git show <гілка>:<тека>/вердикти.txt).
Запуск: cd джерела && python3 -W ignore проби/спори_очима_5293.py <спори_очима.json> <тека вердиктів>"""
import sys, json, io, base64; sys.path.insert(0, "."); from PIL import Image, ImageDraw; import оцінка_образу as О
БОТ = [(98,170),(190,170),(194,336),(214,370),(248,393),(266,418),(270,446),(264,462),(98,462)]
Г = [(100,170),(200,170),(200,380),(270,400),(270,480),(70,480),(70,380),(100,380)]
def фото(ід, г):
    im = Image.new("RGB", (600, 800) if ід == "ф1" else (600, 600), "#efe9e1" if ід == "ф1" else "#8c96a0"); д = ImageDraw.Draw(im)
    if ід == "ф1":
        д.polygon([(170,90),(430,90),(480,130),(480,440),(430,440),(430,470),(170,470),(170,440),(120,440),(120,130)], fill="#7d7f63")
        д.rectangle([250, 110, 349, 399], fill="#cfd8e3"); д.polygon([(200,520),(400,520),(430,760),(170,760)], fill="#6b1f2a")
    for к, п, з in (("#e6dfd2", "#6b5b4c", 0), ("#1d1c1c", "#4a4646", 260)) if ід == "ф2" else ():
        for кк, т in ((к, Г),) if г else ((к, БОТ), (п, [(140,462),(268,462),(266,470),(256,474),(140,474)]), (п, [(98,462),(136,462),(134,480),(100,480)]), (п, [(98,170),(190,170),(190,180),(98,180)])):
            д.polygon([(x + з, y) for x, y in т], fill=кк)
    б = io.BytesIO(); im.save(б, "JPEG", quality=92); return Image.open(б).convert("RGB")
def кадр(im, р):
    W, H = im.size; є = bool(р); р = р or dict(ліво=0, верх=0, право=1000, низ=1000)
    dx, dy = ((р["право"] - р["ліво"]) * .12, (р["низ"] - р["верх"]) * .12) if є else (0, 0)
    л, в, п, н = max(0, р["ліво"] - dx), max(0, р["верх"] - dy), min(1000, р["право"] + dx), min(1000, р["низ"] + dy)
    x0, y0 = round(л / 1000 * W), round(в / 1000 * H); c = im.crop((x0, y0, x0 + round((п - л) / 1000 * W), y0 + round((н - в) / 1000 * H)))
    к = min(1, 128 / max(c.size)); c = c.resize((max(1, round(c.width * к)), max(1, round(c.height * к))), Image.LANCZOS)
    вих = {"дані": base64.urlsafe_b64encode(c.tobytes()).decode(), "ширина": c.width, "висота": c.height}
    if є: вих["ядро"] = {к_: round((р[к_] - (л if к_ in ("ліво", "право") else в)) / ((п - л) if к_ in ("ліво", "право") else (н - в)) * 1000) for к_ in ("ліво", "верх", "право", "низ")}
    return вих
лік = {}
for з in json.load(open(sys.argv[1], encoding="utf-8"))["записи"]:
    т = "%s/%s__%s" % (sys.argv[2], з["гілка"].split("/")[-1], з["тека"].split("/")[-1][:2])
    в = next(в for п in json.load(open(т + "/вердикти.txt", encoding="utf-8"))["прогони"] for в in п["вердикти"])
    ф = {і: фото(і, з.get("варіант_ф2") == "Г") for і in ("ф1", "ф2")}; речі = в["етапи"]["речі"]["речі"]
    пф = {р["ід"]: {і: кадр(ф[і], р["рамка"]) for і in ф if і != р["фото"]} for р in речі if р.get("колір") and р.get("рамка")}
    вв = О._без_кадру(О._виміри(речі, {р["ід"]: кадр(ф[р["фото"]], р.get("рамка")) for р in речі}, пф, None))
    м = next((р for р in вв if з["ід"] in (р["ід"], р.get("ід_моделі"))), {}).get("вимір") or {}
    лік.setdefault(з["очима"] + ("" if з["спір"] else " (без спору)"), []).append(bool(м.get("lab")))
    print("н%-2d %-20s %-5s %-10s було %s → %s %-8s спір=%-5s гілка=%-11s причина=%s · очима: %s" % (з["н"], т.split("/")[-1], з["ід"], з["слово_стилістки"], з["вимір_hex"],
          м.get("hex") or (м.get("ненадійний") or {}).get("hex"), м.get("слово") or "—", bool(м.get("спір")), м.get("гілка"), м.get("причина") or "—", з["очима"]))
print("колір лишився виміром (з записів, де очима правий…):", {к: "%d з %d" % (sum(v), len(v)) for к, v in лік.items()})
